<div class="wp_syntax" style="position:relative;"><table><tr><td class="code"><pre class="language" style="font-family:monospace;">DBCC LOGINFO;</pre></td></tr></table><p class="theCode" style="display:none;">DBCC LOGINFO;</p></div>
