<div class="wp_syntax" style="position:relative;"><table><tr><td class="code"><pre class="language" style="font-family:monospace;"> declare @VLFcnt int,@curr float,
 @FV float, @PV float,
 @i float, @n int;
&nbsp;
select @VLFcnt = 4, --number of VLFs
 @curr = 1, --current value
 @FV = 1, --future value
 @PV = 1, --present value in MB, you can change to be your current log size
 @i = .1, --your current default growth percentage
 @n = 1; --number of iterations
WHILE @FV &lt; 2000000 --that's 2TB, the limit for log file size
 BEGIN
  SELECT @FV/1024 as [logSizeGB], @VLFcnt as [VLF count]
  SET @curr = @FV --want to capture the present value for each iteration
  SELECT @FV = power(@pv*(1+@i),@n) --calc the new value
  IF @FV - @curr &lt; 64.0
   BEGIN
     SET @VLFcnt = @VLFcnt + 4
   END
  IF @FV - @curr &gt;= 64.0 AND @FV - @curr &lt; 1024.0
   BEGIN
    SET @VLFcnt = @VLFcnt + 8
   END
  IF @FV - @curr &gt;= 1024.0
   BEGIN
    SET @VLFcnt = @VLFcnt + 16
   END
  SET @n = @n + 1 --increment @n
 END</pre></td></tr></table><p class="theCode" style="display:none;"> declare @VLFcnt int,@curr float,
 @FV float, @PV float,
 @i float, @n int;

select @VLFcnt = 4, --number of VLFs
 @curr = 1, --current value
 @FV = 1, --future value
 @PV = 1, --present value in MB, you can change to be your current log size
 @i = .1, --your current default growth percentage
 @n = 1; --number of iterations
WHILE @FV &lt; 2000000 --that's 2TB, the limit for log file size
 BEGIN
  SELECT @FV/1024 as [logSizeGB], @VLFcnt as [VLF count]
  SET @curr = @FV --want to capture the present value for each iteration
  SELECT @FV = power(@pv*(1+@i),@n) --calc the new value
  IF @FV - @curr &lt; 64.0
   BEGIN
     SET @VLFcnt = @VLFcnt + 4
   END
  IF @FV - @curr &gt;= 64.0 AND @FV - @curr &lt; 1024.0
   BEGIN
    SET @VLFcnt = @VLFcnt + 8
   END
  IF @FV - @curr &gt;= 1024.0
   BEGIN
    SET @VLFcnt = @VLFcnt + 16
   END
  SET @n = @n + 1 --increment @n
 END</p></div>
";}

a:2:{i:1;s:1673:"
<div class="wp_syntax" style="position:relative;"><table><tr><td class="code"><pre class="powershell" style="font-family:monospace;">invoke<span style="color: pink;">-</span>sqlcmd <span style="color: pink;">-</span>ServerInstance <span style="color: #800000;">&quot;SQLROCKSTAR-ONE\JAMBON&quot;</span> <span style="color: pink;">-</span>Database master <span style="color: #008080; font-style: italic;">-Query</span> <span style="color: #800000;">&quot;SET STATISTICS IO ON;
SELECT c.CustomerID, soh.ShipDate
FROM Sales.SalesOrderDetail sod
INNER JOIN Sales.SalesOrderHeader soh ON sod.SalesOrderID = soh.SalesOrderID
INNER JOIN Sales.Customer c ON c.CustomerID = soh.CustomerID
WHERE sod.SpecialOfferID = 2
AND soh.ShipDate between '2003-01-01 00:00:00.000' and '2010-01-01 00:00:00.000'
AND c.TerritoryID = 9;
SET STATISICS IO OFF&quot;</span> <span style="color: #008080; font-style: italic;">-Verbose</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Out<span style="color: #FF0000;">-File</span></span> c:\scripts\out.txt</pre></td></tr></table><p class="theCode" style="display:none;">invoke-sqlcmd -ServerInstance &quot;SQLROCKSTAR-ONE\JAMBON&quot; -Database master -Query &quot;SET STATISTICS IO ON;
SELECT c.CustomerID, soh.ShipDate
FROM Sales.SalesOrderDetail sod
INNER JOIN Sales.SalesOrderHeader soh ON sod.SalesOrderID = soh.SalesOrderID
INNER JOIN Sales.Customer c ON c.CustomerID = soh.CustomerID
WHERE sod.SpecialOfferID = 2
AND soh.ShipDate between '2003-01-01 00:00:00.000' and '2010-01-01 00:00:00.000'
AND c.TerritoryID = 9;
SET STATISICS IO OFF&quot; -Verbose | Out-File c:\scripts\out.txt</p></div>
