&nbsp;
invoke<span style="color: pink;">-</span>sqlcmd <span style="color: pink;">-</span>ServerInstance <span style="color: #800000;">&quot;SQLROCKSTAR-ONE\JAMBON&quot;</span> <span style="color: pink;">-</span>Database AdventureWorks2012 <span style="color: #008080; font-style: italic;">-Query</span> <span style="color: #800000;">&quot;SET STATISTICS IO ON;
SELECT c.CustomerID, soh.ShipDate
FROM Sales.SalesOrderDetail sod
INNER JOIN Sales.SalesOrderHeader soh ON sod.SalesOrderID = soh.SalesOrderID
INNER JOIN Sales.Customer c ON c.CustomerID = soh.CustomerID
WHERE sod.SpecialOfferID = 2
AND soh.ShipDate between '2003-01-01 00:00:00.000' and '2010-01-01 00:00:00.000'
AND c.TerritoryID = 9;
SET STATISTICS IO OFF&quot;</span> <span style="color: #008080; font-style: italic;">-Verbose</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Out<span style="color: #FF0000;">-File</span></span> c:\scripts\out.txt
&nbsp;
<span style="color: #008080; font-weight: bold;">Write-Host</span> <span style="color: #800000;">&quot;<span style="color: #008080; font-weight: bold;">`r</span><span style="color: #008080; font-weight: bold;">`n</span><span style="color: #008080; font-weight: bold;">`r</span><span style="color: #008080; font-weight: bold;">`n</span>&quot;</span>
<span style="color: #008080; font-weight: bold;">Write-Host</span> <span style="color: #800000;">&quot;End customer query&quot;</span>
<span style="color: #008080; font-weight: bold;">Write-Host</span> <span style="color: #800000;">&quot;<span style="color: #008080; font-weight: bold;">`r</span><span style="color: #008080; font-weight: bold;">`n</span><span style="color: #008080; font-weight: bold;">`r</span><span style="color: #008080; font-weight: bold;">`n</span>&quot;</span>
&nbsp;
<span style="color: #008080; font-weight: bold;">Stop-Transcript</span>
&nbsp;
<span style="color: #008080; font-weight: bold;">Invoke-Item</span> $TranscriptFile</pre></td></tr></table><p class="theCode" style="display:none;">$TranscriptFile = &quot;c:\scripts\trans.txt&quot;
Start-Transcript -Path $TranscriptFile

Write-Host &quot;Running customer query&quot;
Write-Host &quot;`r`n`r`n&quot;

invoke-sqlcmd -ServerInstance &quot;SQLROCKSTAR-ONE\JAMBON&quot; -Database AdventureWorks2012 -Query &quot;SET STATISTICS IO ON;
SELECT c.CustomerID, soh.ShipDate
FROM Sales.SalesOrderDetail sod
INNER JOIN Sales.SalesOrderHeader soh ON sod.SalesOrderID = soh.SalesOrderID
INNER JOIN Sales.Customer c ON c.CustomerID = soh.CustomerID
WHERE sod.SpecialOfferID = 2
AND soh.ShipDate between '2003-01-01 00:00:00.000' and '2010-01-01 00:00:00.000'
AND c.TerritoryID = 9;
SET STATISTICS IO OFF&quot; -Verbose | Out-File c:\scripts\out.txt

Write-Host &quot;`r`n`r`n&quot;
Write-Host &quot;End customer query&quot;
Write-Host &quot;`r`n`r`n&quot;

Stop-Transcript

Invoke-Item $TranscriptFile</p></div>
