";i:2;s:5793:"
<div class="wp_syntax" style="position:relative;"><table><tr><td class="code"><pre class="tsql" style="font-family:monospace;"><span style="color: #0000FF;">USE</span> tst_autogrowth;
GO
&nbsp;
<span style="color: #0000FF;">SELECT</span> a.<span style="color: #202020;">fileid</span>
, <span style="color: #0000FF;">CONVERT</span><span style="color: #808080;">&#40;</span><span style="color: #0000FF;">DECIMAL</span><span style="color: #808080;">&#40;</span><span style="color: #000;">12</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span>,<span style="color: #FF00FF;">ROUND</span><span style="color: #808080;">&#40;</span>a.<span style="color: #0000FF;">size</span><span style="color: #808080;">/</span><span style="color: #000;">128.000</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>FILE_SIZE_MB<span style="color: #808080;">&#93;</span>
, <span style="color: #0000FF;">CONVERT</span><span style="color: #808080;">&#40;</span><span style="color: #0000FF;">DECIMAL</span><span style="color: #808080;">&#40;</span><span style="color: #000;">12</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span>,<span style="color: #FF00FF;">ROUND</span><span style="color: #808080;">&#40;</span><span style="color: #FF00FF;">FILEPROPERTY</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">name</span>,<span style="color: #FF0000;">'SpaceUsed'</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">/</span><span style="color: #000;">128.000</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>SPACE_USED_MB<span style="color: #808080;">&#93;</span>
, <span style="color: #0000FF;">CONVERT</span><span style="color: #808080;">&#40;</span><span style="color: #0000FF;">DECIMAL</span><span style="color: #808080;">&#40;</span><span style="color: #000;">12</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span>,<span style="color: #FF00FF;">ROUND</span><span style="color: #808080;">&#40;</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">size</span><span style="color: #808080;">-</span><span style="color: #FF00FF;">FILEPROPERTY</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">name</span>,<span style="color: #FF0000;">'SpaceUsed'</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">/</span><span style="color: #000;">128.000</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>FREE_SPACE_MB<span style="color: #808080;">&#93;</span>
, <span style="color: #0000FF;">CONVERT</span><span style="color: #808080;">&#40;</span><span style="color: #0000FF;">DECIMAL</span><span style="color: #808080;">&#40;</span><span style="color: #000;">12</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span>,<span style="color: #FF00FF;">ROUND</span><span style="color: #808080;">&#40;</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">size</span><span style="color: #808080;">-</span><span style="color: #FF00FF;">FILEPROPERTY</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">name</span>,<span style="color: #FF0000;">'SpaceUsed'</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">/</span><span style="color: #000;">128.000</span><span style="color: #808080;">/</span><span style="color: #808080;">&#40;</span>a.<span style="color: #0000FF;">size</span><span style="color: #808080;">/</span><span style="color: #000;">128.000</span><span style="color: #808080;">&#41;</span>,<span style="color: #000;">2</span><span style="color: #808080;">&#41;</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>FREE_PCT_MB<span style="color: #808080;">&#93;</span>
, <span style="color: #0000FF;">left</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">NAME</span>,<span style="color: #000;">15</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>NAME<span style="color: #808080;">&#93;</span>
, <span style="color: #0000FF;">left</span><span style="color: #808080;">&#40;</span>a.<span style="color: #202020;">FILENAME</span>,<span style="color: #000;">30</span><span style="color: #808080;">&#41;</span> <span style="color: #0000FF;">AS</span> <span style="color: #808080;">&#91;</span>FILENAME<span style="color: #808080;">&#93;</span>
<span style="color: #0000FF;">FROM</span> sys.<span style="color: #202020;">sysfiles</span> a;
GO</pre></td></tr></table><p class="theCode" style="display:none;">USE tst_autogrowth;
GO

SELECT a.fileid
, CONVERT(DECIMAL(12,2),ROUND(a.size/128.000,2)) AS [FILE_SIZE_MB]
, CONVERT(DECIMAL(12,2),ROUND(FILEPROPERTY(a.name,'SpaceUsed')/128.000,2)) AS [SPACE_USED_MB]
, CONVERT(DECIMAL(12,2),ROUND((a.size-FILEPROPERTY(a.name,'SpaceUsed'))/128.000,2)) AS [FREE_SPACE_MB]
, CONVERT(DECIMAL(12,2),ROUND((a.size-FILEPROPERTY(a.name,'SpaceUsed'))/128.000/(a.size/128.000),2)) AS [FREE_PCT_MB]
, left(a.NAME,15) AS [NAME]
, left(a.FILENAME,30) AS [FILENAME]
FROM sys.sysfiles a;
GO</p></div>
